func TestParseDurationDays(t *testing.T) {
	for in, want := range map[string]time.Duration{
		"30d": 720 * time.Hour, "1d12h": 36 * time.Hour, "-2d": -48 * time.Hour,
		"0d": 0, "90": 90 * time.Second, "1m30s": 90 * time.Second, "-1h": -time.Hour,
	} {
		if d, err := parseDuration(in); in != "90" && (err != nil || d != want) {
			t.Errorf("parseDuration(%q) = %v, %v; want %v", in, d, err, want)
		}
	}
	for _, in := range []string{"d", "1.5d", "1d-2h", "--1d", "1dd", "x30d", "99999999999d"} {
		if d, err := parseDuration(in); err == nil {
			t.Errorf("parseDuration(%q) = %v, want error", in, d)
		}
	}
}
